export function getFAQBySlug(slug: string): FAQCategoria | undefined {
  return faqCategorias.find(c => c.slug === slug);
}

export function getTotalPerguntas(): number {
  return faqCategorias.reduce((total, cat) => total + cat.perguntas.length, 0);
}
